47|     if (quantity < 1) {
48|       throw new Error("quantity must be at least one");
49|     }
50|     const unit = this.costOf(sku) * BASE_MARKUP;
51|     const discounted = unit * (1 - DISCOUNTS[tier]);
52|     const lineTotal = discounted * quantity;
