2| package warehouse
3| 
4| import (
5| 	"fmt"
6| 	"math"
7| 	"sort"
8| )
9| 
10| // BaseMarkup is applied to every cost price before discounts.
11| const BaseMarkup = 1.35
12| 
13| // Currency is the only currency this book quotes in.
14| const Currency = "EUR"
15| 
16| // Tier names a customer pricing tier.
17| type Tier string
18| 
19| // The tiers the business sells at.
20| const (
21| 	TierRetail    Tier = "retail"
22| 	TierTrade     Tier = "trade"
23| 	TierWholesale Tier = "wholesale"
24| )
25| 
26| var discounts = map[Tier]float64{
27| 	TierRetail:    0.0,
28| 	TierTrade:     0.10,
29| 	TierWholesale: 0.22,
30| }
31| 
32| // PriceBook holds cost prices keyed by SKU.
33| type PriceBook struct {
34| 	costs map[string]float64
35| }
36| 
37| // NewPriceBook copies the cost table so callers cannot mutate it later.
38| func NewPriceBook(costs map[string]float64) (*PriceBook, error) {
39| 	copied := make(map[string]float64, len(costs))
40| 	for sku, cost := range costs {
41| 		if cost < 0 {
42| 			return nil, fmt.Errorf("negative cost price for %q", sku)
43| 		}
44| 		copied[sku] = cost
45| 	}
46| 	return &PriceBook{costs: copied}, nil
47| }
48| 
49| // CostOf returns the cost price for a SKU.
50| func (p *PriceBook) CostOf(sku string) (float64, error) {
51| 	cost, ok := p.costs[sku]
52| 	if !ok {
53| 		return 0, fmt.Errorf("no cost price recorded for %q", sku)
54| 	}
55| 	return cost, nil
56| }
57| 
58| // Quote prices a line at a tier.
59| func (p *PriceBook) Quote(sku string, tier Tier, quantity int) (float64, error) {
60| 	if quantity < 1 {
61| 		return 0, fmt.Errorf("quantity must be at least one, got %d", quantity)
62| 	}
63| 	cost, err := p.CostOf(sku)
64| 	if err != nil {
65| 		return 0, err
66| 	}
67| 	// Discounts apply to the marked-up price, not the cost price.
68| 	unit := cost * BaseMarkup * (1 - discounts[tier])
69| 	return math.Round(unit*float64(quantity)*100) / 100, nil
70| }
71| 
72| // PriceList returns every SKU with its unit price at a tier, in SKU order.
73| func (p *PriceBook) PriceList(tier Tier) ([][2]interface{}, error) {
74| 	skus := make([]string, 0, len(p.costs))
75| 	for sku := range p.costs {
76| 		skus = append(skus, sku)
77| 	}
78| 	sort.Strings(skus)
79| 
80| 	rows := make([][2]interface{}, 0, len(skus))
81| 	for _, sku := range skus {
82| 		price, err := p.Quote(sku, tier, 1)
83| 		if err != nil {
84| 			return nil, err
85| 		}
86| 		rows = append(rows, [2]interface{}{sku, price})
87| 	}
88| 	return rows, nil
89| }
